-- bootstrap_extensions: production only; local tests provide non-networking facades.
create extension if not exists pg_cron;
create extension if not exists pg_net with schema extensions;
-- end_bootstrap_extensions
lock table public.exam_attempts in share row exclusive mode;
do $$begin if exists(select 1 from public.exam_attempts where organization_id='6e143c55-7be5-4e6e-9f1a-8f8db429956a') then raise exception 'Review active operational data and backup before applying';end if;end$$;
create table private.worker_transport(id boolean primary key default true check(id),public_anon_jwt text not null default '',full_worker_approved boolean not null default false);alter table private.worker_transport enable row level security;revoke all on private.worker_transport from public,anon,authenticated;insert into private.worker_transport default values;
create table private.app_settings(organization_id uuid primary key references public.organizations(id),name text not null default 'EDUTARA CBT',subtitle text not null default 'Ujian madrasah',login_logo_id uuid references public.media_assets(id),login_background_id uuid references public.media_assets(id),violation_limit int not null default 3 check(violation_limit between 1 and 100),canvas_enabled boolean not null default true,results_enabled boolean not null default true,automation_enabled boolean not null default false,reminders_enabled boolean not null default false,retention_days int not null default 180 check(retention_days between 7 and 730),smtp_sender text not null default '',reminder_template text not null default 'Assalamu’alaikum {{nama}}. Periode input soal berakhir {{periode}}. Kekurangan target: {{kekurangan}}. Silakan buka {{tautan}}.',version int not null default 1);
create table private.secret_refs(organization_id uuid not null references public.organizations(id),key text not null check(key in ('smtp_password','ai_api_key','drive_access_token')),vault_id uuid not null,primary key(organization_id,key));
create table private.work_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),kind text not null check(kind in ('backup','reminder','smtp_probe','retention')),dedupe text not null,payload jsonb not null default '{}',status text not null default 'queued' check(status in ('queued','running','succeeded','failed','blocked','uncertain')),progress int not null default 0,attempts int not null default 0,step int not null default 0,lease uuid,lease_until timestamptz,nonce_hash text,nonce_until timestamptz,next_attempt timestamptz not null default now(),result_path text,result_checksum text,error text,requested_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,kind,dedupe));
create index work_pending on private.work_jobs(next_attempt) where status in ('queued','failed');
create table private.backup_rows(job_id uuid not null references private.work_jobs(id),ordinal bigint not null,table_name text not null,payload jsonb not null,primary key(job_id,ordinal));
create table private.backup_parts(job_id uuid not null references private.work_jobs(id),number int not null,path text not null,sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),bytes bigint not null,kind text not null,metadata jsonb not null default '{}',primary key(job_id,number));
create table private.legacy_records(organization_id uuid not null references public.organizations(id),entity text not null,legacy_id text not null,target_id uuid,source_hash text not null,payload jsonb not null,status text not null check(status in ('staged','loaded','quarantined')),reason text,primary key(organization_id,entity,legacy_id));
create table private.job_events(id bigint generated always as identity primary key,job_id uuid not null references private.work_jobs(id),event text not null,detail text,created_at timestamptz not null default now());
do $$declare t text;begin foreach t in array array['app_settings','secret_refs','work_jobs','backup_rows','backup_parts','legacy_records','job_events'] loop execute format('alter table private.%I enable row level security',t);execute format('revoke all on private.%I from public,anon,authenticated',t);end loop;end$$;
insert into private.app_settings(organization_id) select id from public.organizations on conflict do nothing;
-- Never update/delete an audit event; authenticated writers remain restricted to domain RPCs.
create function private.audit_append_only() returns trigger language plpgsql set search_path='' as $$begin raise exception 'Audit is append-only';end$$;
revoke all on function private.audit_append_only() from public,anon,authenticated;
create trigger audit_append_only before update or delete on public.audit_logs for each row execute function private.audit_append_only();
create index audit_org_time on public.audit_logs(organization_id,created_at desc);
-- Explicit public mirror: no anonymous access to the private schema or secret-bearing settings.
create table public.app_branding_data(organization_id uuid primary key references public.organizations(id),name text not null,subtitle text not null,login_logo_id uuid,login_background_id uuid);
alter table public.app_branding_data enable row level security;revoke all on public.app_branding_data from public,anon,authenticated;grant select on public.app_branding_data to anon,authenticated;
create policy public_branding_read on public.app_branding_data for select to anon,authenticated using(organization_id='6e143c55-7be5-4e6e-9f1a-8f8db429956a');
insert into public.app_branding_data select organization_id,name,subtitle,login_logo_id,login_background_id from private.app_settings;
create function private.sync_branding() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.app_branding_data values(new.organization_id,new.name,new.subtitle,new.login_logo_id,new.login_background_id) on conflict(organization_id) do update set name=excluded.name,subtitle=excluded.subtitle,login_logo_id=excluded.login_logo_id,login_background_id=excluded.login_background_id;return new;end$$;
revoke all on function private.sync_branding() from public,anon,authenticated;
create trigger sync_branding after insert or update on private.app_settings for each row execute function private.sync_branding();
grant select(id,object_path,mime_type) on public.media_assets to anon;grant select on storage.objects to anon;
create policy login_brand_media on public.media_assets for select to anon using(exists(select 1 from public.app_branding_data b where b.login_logo_id=id or b.login_background_id=id));
create policy login_brand_storage on storage.objects for select to anon using(bucket_id='exam-media' and exists(select 1 from public.media_assets m join public.app_branding_data b on m.id=b.login_logo_id or m.id=b.login_background_id where m.object_path=name));
create function public.app_branding() returns jsonb language sql security invoker set search_path='' as $$select coalesce((select jsonb_build_object('name',name,'subtitle',subtitle,'logo_id',login_logo_id,'background_id',login_background_id) from public.app_branding_data where organization_id='6e143c55-7be5-4e6e-9f1a-8f8db429956a'),'{}')$$;
revoke all on function public.app_branding() from public;grant execute on function public.app_branding() to anon,authenticated;
create function private.enqueue_work(org uuid,kind0 text,dedupe0 text,payload0 jsonb default '{}',actor0 uuid default null) returns uuid language plpgsql security definer set search_path='' as $$declare target uuid;begin insert into private.work_jobs(organization_id,kind,dedupe,payload,requested_by) values(org,kind0,dedupe0,payload0,actor0) on conflict(organization_id,kind,dedupe) do update set dedupe=excluded.dedupe returning id into target;insert into public.job_runs(organization_id,kind,idempotency_key,status) values(org,kind0,dedupe0,'pending') on conflict do nothing;return target;end$$;
create function private.dispatch_work(target uuid) returns void language plpgsql security definer set search_path='' as $$declare j private.work_jobs;token text:=gen_random_uuid()::text;transport private.worker_transport;begin select * into transport from private.worker_transport;select * into j from private.work_jobs where id=target for update;if not found or j.status not in ('queued','failed') or j.attempts>=5 or j.next_attempt>clock_timestamp() then return;end if;if j.kind<>'backup' and not transport.full_worker_approved then update private.work_jobs set status='blocked',error='Worker email/retensi belum diaktifkan' where id=target;return;end if;if transport.public_anon_jwt='' then update private.work_jobs set status='blocked',error='Transport backup belum dikonfigurasi' where id=target;return;end if;update private.work_jobs set nonce_hash=encode(extensions.digest(token,'sha256'),'hex'),nonce_until=clock_timestamp()+interval '5 minutes',next_attempt=clock_timestamp()+interval '2 minutes' where id=target;perform net.http_post(url:='https://cwklpfplqoofvehlyfvd.supabase.co/functions/v1/'||case when transport.full_worker_approved then 'operations-worker' else 'backup-worker' end,headers:=jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||transport.public_anon_jwt),body:=jsonb_build_object('id',target,'nonce',token),timeout_milliseconds:=10000);end$$;
create function private.system_command(input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare op text:=input->>'action';org uuid:=private.actor_org();s private.app_settings;j private.work_jobs;target uuid:=nullif(input->>'id','')::uuid;secret uuid;result jsonb;v jsonb;begin
 if not private.is_admin() then raise exception 'AUTH: Hanya Admin';end if;
 insert into private.app_settings(organization_id) values(org) on conflict do nothing;
 if op='get' then select to_jsonb(a)-'organization_id' into result from private.app_settings a where organization_id=org;return result||jsonb_build_object('timezone',(select timezone from public.organizations where id=org),'secrets',coalesce((select jsonb_object_agg(key,true) from private.secret_refs where organization_id=org),'{}'),'scheduler','Supabase Cron: edutara-operations','secret_readback',false,'worker_capabilities',jsonb_build_object('backup',(select public_anon_jwt<>'' from private.worker_transport),'smtp',(select full_worker_approved from private.worker_transport),'retention',(select full_worker_approved from private.worker_transport)));end if;
 if op='audit' then with f as(select a.*,p.full_name actor from public.audit_logs a left join public.profiles p on p.id=a.actor_id where a.organization_id=org and (coalesce(input->>'search','')='' or a.action ilike '%'||(input->>'search')||'%' or coalesce(p.full_name,'') ilike '%'||(input->>'search')||'%' or a.target_type ilike '%'||(input->>'search')||'%') and (nullif(input->>'from','') is null or a.created_at>=(input->>'from')::timestamptz) and (nullif(input->>'until','') is null or a.created_at<(input->>'until')::timestamptz)) select jsonb_build_object('total',(select count(*) from f),'rows',coalesce(jsonb_agg(to_jsonb(v) order by v.created_at desc),'[]')) into result from(select * from f order by created_at desc limit 50 offset (greatest(1,coalesce((input->>'page')::int,1))-1)*50)v;return result;end if;
 if op='jobs' then select coalesce(jsonb_agg(to_jsonb(v) order by created_at desc),'[]') into result from(select id,kind,status,progress,attempts,step,error,created_at,updated_at,result_path,result_checksum,payload->>'outcome' outcome from private.work_jobs where organization_id=org order by created_at desc limit 100)v;return result;end if;
 if op='parts' then if not exists(select 1 from private.work_jobs where id=target and organization_id=org and kind='backup' and status='succeeded') then raise exception 'AUTH: Backup belum tersedia';end if;select coalesce(jsonb_agg(to_jsonb(p)-'job_id' order by number),'[]') into result from private.backup_parts p where job_id=target;return result;end if;
 if op='secret' then
 if input->>'key' not in ('smtp_password','ai_api_key','drive_access_token') or length(coalesce(input->>'value','')) not between 8 and 10000 then raise exception 'Secret tidak valid';end if;
 select vault_id into secret from private.secret_refs where organization_id=org and key=input->>'key' for update;
 if found then perform vault.update_secret(secret,input->>'value');else select vault.create_secret(input->>'value','edutara:'||org::text||':'||(input->>'key')) into secret;insert into private.secret_refs values(org,input->>'key',secret);end if;result:='{"configured":true,"readback":false}';
 elsif op='save' then
 v:=input->'settings';select * into s from private.app_settings where organization_id=org for update;
 if s.version is distinct from (input->>'version')::int then raise exception 'CONFLICT: Pengaturan berubah';end if;
 if length(trim(coalesce(v->>'name',''))) not between 1 and 100 or length(coalesce(v->>'subtitle',''))>200 or length(coalesce(v->>'reminder_template','')) not between 20 and 5000 or not exists(select 1 from pg_timezone_names where name=v->>'timezone') then raise exception 'Pengaturan tidak valid';end if;
 if exists(select 1 from unnest(array[nullif(v->>'login_logo_id','')::uuid,nullif(v->>'login_background_id','')::uuid]) x where x is not null and not exists(select 1 from public.media_assets m where m.id=x and m.organization_id=org and m.mime_type like 'image/%')) then raise exception 'Logo/background tidak tersedia';end if;
 if (v->>'reminders_enabled')::boolean and not (select full_worker_approved from private.worker_transport) then raise exception 'Worker email belum diaktifkan';end if;
 if (v->>'reminders_enabled')::boolean and (coalesce(v->>'smtp_sender','') !~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' or not exists(select 1 from private.secret_refs where organization_id=org and key='smtp_password')) then raise exception 'Email Gmail dan secret SMTP wajib sebelum pengingat aktif';end if;
 update private.app_settings set name=trim(v->>'name'),subtitle=v->>'subtitle',login_logo_id=nullif(v->>'login_logo_id','')::uuid,login_background_id=nullif(v->>'login_background_id','')::uuid,violation_limit=(v->>'violation_limit')::int,canvas_enabled=(v->>'canvas_enabled')::bool,results_enabled=(v->>'results_enabled')::bool,automation_enabled=(v->>'automation_enabled')::bool,reminders_enabled=(v->>'reminders_enabled')::bool,retention_days=(v->>'retention_days')::int,smtp_sender=v->>'smtp_sender',reminder_template=v->>'reminder_template',version=version+1 where organization_id=org;
 update public.organizations set name=trim(v->>'name'),timezone=v->>'timezone' where id=org;result:='{"saved":true}';
 elsif op in ('backup','smtp_probe') then
 if op='smtp_probe' and not (select full_worker_approved from private.worker_transport) then raise exception 'Worker SMTP belum diaktifkan';end if;
 if not exists(select 1 from private.work_jobs where organization_id=org and kind=op and dedupe=(input->>'request_id')::uuid::text) then
 if not public.consume_login_budget('system-work:'||org::text||':'||op) then raise exception 'Batas 10 permintaan per 15 menit';end if;
 if op='backup' and (select count(*) from private.work_jobs where organization_id=org and kind='backup' and status in ('queued','running'))>=2 then raise exception 'Maksimal dua backup berjalan/menunggu';end if;end if;
 target:=private.enqueue_work(org,op,(input->>'request_id')::uuid::text,'{}',auth.uid());perform private.dispatch_work(target);result:=jsonb_build_object('id',target,'queued',true);
 elsif op='cancel_backup' then
 select * into j from private.work_jobs where id=target and organization_id=org for update;
 if not found or j.kind<>'backup' or j.status='succeeded' or length(trim(coalesce(input->>'reason','')))<5 or input->>'confirmation'<>'KONFIRMASI' then raise exception 'Backup/konfirmasi pembatalan tidak valid';end if;
 update private.work_jobs set status='blocked',payload=payload||'{"outcome":"cancelled"}'::jsonb,error='Dibatalkan Admin; sumber data tetap dipertahankan',nonce_hash=null,lease=null,lease_until=null where id=target;delete from private.backup_rows where job_id=target;insert into private.job_events(job_id,event,detail) values(target,'cancelled',left(input->>'reason',1000));result:='{"cancelled":true}';
 elsif op='resolve_email' then
 select * into j from private.work_jobs where id=target and organization_id=org for update;
 if not found or j.kind<>'reminder' or j.status<>'uncertain' or input->>'resolution' not in ('sent','not_sent') or length(trim(coalesce(input->>'reason','')))<5 or input->>'confirmation'<>'KONFIRMASI' then raise exception 'Rekonsiliasi email tidak valid';end if;
 update private.work_jobs set status=case when input->>'resolution'='sent' then 'succeeded' else 'queued' end,payload=(payload-'delivery_started')||jsonb_build_object('outcome','reconciled_'||(input->>'resolution')),attempts=0,next_attempt=clock_timestamp(),error=null where id=target;insert into private.job_events(job_id,event,detail) values(target,'email_reconciled',left(input->>'reason',1000));if input->>'resolution'='not_sent' then perform private.dispatch_work(target);end if;result:='{"saved":true}';
 elsif op='retry' then
 select * into j from private.work_jobs where id=target and organization_id=org for update;if not found or (j.status not in ('failed','blocked') or j.payload->>'outcome'='cancelled') then raise exception 'Hanya job gagal/terblokir dapat dicoba ulang; job tidak pasti perlu rekonsiliasi';end if;
 update private.work_jobs set status='queued',attempts=0,error=null,next_attempt=clock_timestamp() where id=target;perform private.dispatch_work(target);result:='{"queued":true}';
 else raise exception 'Aksi sistem tidak dikenal';end if;
 insert into public.audit_logs(organization_id,actor_id,action,target_type,target_id) values(org,auth.uid(),'SYSTEM_'||op,'system',coalesce(target::text,input->>'key','settings'));return result;
end$$;
create function public.system_command(input jsonb) returns jsonb language sql security invoker set search_path='' as $$select private.system_command(input)$$;
revoke all on function private.enqueue_work(uuid,text,text,jsonb,uuid),private.dispatch_work(uuid),private.system_command(jsonb),public.system_command(jsonb) from public,anon,authenticated;grant execute on function private.system_command(jsonb),public.system_command(jsonb) to authenticated;
-- Foundation audit_mutation triggers already cover profiles and master data.
-- STABLE reads share one statement snapshot; capture inserts that materialized snapshot once.
create function private.backup_data(org uuid) returns table(table_name text,seq bigint,payload jsonb) language plpgsql stable security definer set search_path='' as $$declare t record;predicate text;begin
 for t in select n.nspname schema,c.relname name from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind='r' and c.relname not in ('secret_refs','backup_rows','backup_parts','login_budgets','attempt_requests','authoring_requests','grading_requests','operational_requests') order by n.nspname,c.relname loop
 if t.schema='public' and t.name='organizations' then predicate:='r.id=$1';
 elsif exists(select 1 from information_schema.columns where information_schema.columns.table_schema=t.schema and information_schema.columns.table_name=t.name and column_name='organization_id') then predicate:='r.organization_id=$1';
 elsif exists(select 1 from information_schema.columns where information_schema.columns.table_schema=t.schema and information_schema.columns.table_name=t.name and column_name='attempt_id') then predicate:='exists(select 1 from public.exam_attempts p where p.id=r.attempt_id and p.organization_id=$1)';
 elsif exists(select 1 from information_schema.columns where information_schema.columns.table_schema=t.schema and information_schema.columns.table_name=t.name and column_name='exam_id') then predicate:='exists(select 1 from public.exams p where p.id=r.exam_id and p.organization_id=$1)';
 elsif exists(select 1 from information_schema.columns where information_schema.columns.table_schema=t.schema and information_schema.columns.table_name=t.name and column_name='question_id') then predicate:='exists(select 1 from public.questions p where p.id=r.question_id and p.organization_id=$1)';
 elsif t.name='supervisor_substitutions' then predicate:='exists(select 1 from public.supervisor_assignments p where p.id=r.assignment_id and p.organization_id=$1)';
 elsif t.name='notification_receipts' then predicate:='exists(select 1 from private.notifications p where p.id=r.notification_id and p.organization_id=$1)';
 elsif t.name='job_events' then predicate:='exists(select 1 from private.work_jobs p where p.id=r.job_id and p.organization_id=$1)';
 else continue;end if;
 return query execute format('select %L::text,row_number() over(order by to_jsonb(r)::text),to_jsonb(r) from %I.%I r where %s',t.schema||'.'||t.name,t.schema,t.name,predicate) using org;
 end loop;
 return query select 'auth.identities_safe'::text,row_number() over(order by u.id),jsonb_build_object('id',u.id,'email',u.email,'email_confirmed',u.email_confirmed_at is not null,'reactivation_required',true) from auth.users u join public.profiles p on p.id=u.id where p.organization_id=org;
end$$;
create function private.backup_access(target uuid) returns boolean language sql stable security definer set search_path='' as $$select private.is_admin() and exists(select 1 from private.work_jobs where id=target and organization_id=private.actor_org() and kind='backup')$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('system-backups','system-backups',false,52428800,array['application/json','application/octet-stream']);
create policy backup_admin_read on storage.objects for select to authenticated using(bucket_id='system-backups' and exists(select 1 from private.work_jobs j where private.backup_access(j.id) and j.status='succeeded' and split_part(name,'/',1)=j.organization_id::text and split_part(name,'/',2)=j.id::text));
create function private.worker_command(input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare op text:=input->>'action';target uuid:=(input->>'id')::uuid;j private.work_jobs;result jsonb;v jsonb;count0 int;size0 bigint;part int;settings jsonb;begin
 select * into j from private.work_jobs where id=target for update;if not found then raise exception 'AUTH: Job tidak tersedia';end if;
 if op in ('claim','backup_claim') then
 if op='backup_claim' and j.kind<>'backup' then raise exception 'Backup-only worker';end if;
 if j.kind<>'backup' and not (select full_worker_approved from private.worker_transport) then raise exception 'Full worker not approved';end if;
 if j.status='succeeded' or j.nonce_until<clock_timestamp() or j.nonce_hash is distinct from encode(extensions.digest(coalesce(input->>'nonce',''),'sha256'),'hex') then raise exception 'AUTH: Token dispatch tidak valid/kedaluwarsa';end if;
 if j.status='running' and j.lease_until>clock_timestamp() then return '{"busy":true}';end if;
 if j.attempts>=5 then raise exception 'Batas retry';end if;
 update private.work_jobs set status='running',attempts=attempts+1,lease=gen_random_uuid(),lease_until=clock_timestamp()+interval '4 minutes',payload=payload-'delivery_started',nonce_hash=null,updated_at=clock_timestamp() where id=target returning * into j;
 update public.job_runs set status='running' where organization_id=j.organization_id and kind=j.kind and idempotency_key=j.dedupe;
 select to_jsonb(s)||jsonb_build_object('timezone',(select timezone from public.organizations where id=j.organization_id)) into settings from private.app_settings s where organization_id=j.organization_id;
 if j.kind in ('reminder','smtp_probe') then settings:=settings||jsonb_build_object('smtp_password',(select decrypted_secret from vault.decrypted_secrets where id=(select vault_id from private.secret_refs where organization_id=j.organization_id and key='smtp_password')));end if;
 return jsonb_build_object('id',j.id,'kind',j.kind,'organization_id',j.organization_id,'lease',j.lease,'payload',j.payload,'step',j.step,'settings',settings,'created_at',j.created_at);end if;
 if j.status<>'running' or j.lease is distinct from (input->>'lease')::uuid or j.lease_until<clock_timestamp() then raise exception 'CONFLICT: Lease berubah';end if;
 if op='sending' then if j.kind<>'reminder' then raise exception 'Hanya pengingat';end if;update private.work_jobs set payload=payload||'{"delivery_started":true}'::jsonb where id=target;return '{"saved":true}';end if;
 if op='reminder_check' then
 select jsonb_build_object('eligible',coalesce(s.reminders_enabled and p.enabled and p.ends_at=(j.payload->>'period_end')::timestamptz and p.ends_at>clock_timestamp() and p.ends_at<=clock_timestamp()+interval '24 hours' and pr.active and pr.role='teacher' and u.email_confirmed_at is not null and lower(u.email)=j.payload->>'email' and exists(select 1 from jsonb_array_elements(coalesce(j.payload->'deficit','[]')) d join public.exams e on e.id=(d->>'exam_id')::uuid and e.organization_id=j.organization_id join public.exam_type_configs c on c.exam_id=e.id and c.type=d->>'type' where e.status in ('draft','scheduled') and c.enabled and c.max_questions>(select count(*) from public.questions q where q.exam_id=e.id and q.type=c.type and q.archived_at is null) and not exists(select 1 from public.exam_classes ec where ec.exam_id=e.id and not exists(select 1 from public.teacher_assignments ta where ta.teacher_id=pr.id and ta.class_id=ec.class_id and ta.subject_id=e.subject_id and ta.active))),false)) into result from public.profiles pr join auth.users u on u.id=pr.id join private.app_settings s on s.organization_id=pr.organization_id left join public.authoring_periods p on p.organization_id=pr.organization_id where pr.id=(j.payload->>'teacher_id')::uuid and pr.organization_id=j.organization_id;return coalesce(result,'{"eligible":false}');end if;
 if op='capture' then
 if j.kind<>'backup' then raise exception 'Hanya backup';end if;
 if not exists(select 1 from private.backup_rows where job_id=target) then insert into private.backup_rows select target,row_number() over(order by d.table_name,d.seq),d.table_name,d.payload from private.backup_data(j.organization_id)d;end if;
 select count(*),coalesce(sum(octet_length(payload::text)),0) into count0,size0 from private.backup_rows where job_id=target;if count0>100000 or size0>268435456 then raise exception 'Backup melebihi 100.000 row / 256 MiB data; gunakan dump PostgreSQL';end if;
 return jsonb_build_object('rows',count0,'bytes',size0,'tables',(select jsonb_object_agg(table_name,n) from(select table_name,count(*) n from private.backup_rows where job_id=target group by table_name)s),'migrations',(select jsonb_agg(jsonb_build_object('version',version,'name',name,'statements',statements) order by version) from supabase_migrations.schema_migrations));end if;
 if op='data' then select coalesce(jsonb_agg(jsonb_build_object('ordinal',ordinal,'table',table_name,'record',payload) order by ordinal),'[]') into result from(select * from private.backup_rows where job_id=target and ordinal>coalesce((input->>'cursor')::bigint,0) order by ordinal limit 100)x;return result;end if;
 if op='objects' then select coalesce(jsonb_agg(v order by v->>'bucket',v->>'path'),'[]') into result from(select distinct case table_name when 'public.media_assets' then jsonb_build_object('bucket','exam-media','path',payload->>'object_path','expected_bytes',payload->'byte_size','expected_hash',payload->>'sha256') when 'public.answer_media' then jsonb_build_object('bucket','attempt-canvas','path',payload->>'object_path','expected_bytes',payload->'byte_size','expected_hash',payload->>'checksum') when 'private.export_jobs' then case when payload->>'status'='ready' then jsonb_build_object('bucket','exam-reports','path',payload->>'result_path','expected_bytes',payload->'byte_size') end when 'private.card_jobs' then case when payload->>'status'='ready' then jsonb_build_object('bucket','exam-cards','path',payload->>'path') end end v from private.backup_rows where job_id=target and table_name in ('public.media_assets','public.answer_media','private.export_jobs','private.card_jobs'))x where v is not null;return result;end if;
 if op='parts' then select coalesce(jsonb_agg(to_jsonb(p)-'job_id' order by number),'[]') into result from private.backup_parts p where job_id=target;return result;end if;
 if op='part' then
 if input->>'path' not like j.organization_id::text||'/'||j.id::text||'/%' or (input->>'bytes')::bigint not between 1 and 52428800 or input->>'sha256' !~ '^[0-9a-f]{64}$' then raise exception 'Bagian backup tidak valid';end if;
 insert into private.backup_parts(job_id,number,path,sha256,bytes,kind,metadata) values(target,(input->>'number')::int,input->>'path',input->>'sha256',(input->>'bytes')::bigint,input->>'kind',coalesce(input->'metadata','{}')) on conflict(job_id,number) do nothing;return '{"saved":true}';end if;
 if op='checkpoint' then update private.work_jobs set payload=payload||coalesce(input->'payload','{}'),step=step+1,progress=least(95,coalesce((input->>'progress')::int,progress)),status='queued',attempts=0,next_attempt=clock_timestamp(),lease=null,lease_until=null,updated_at=clock_timestamp() where id=target;perform private.dispatch_work(target);return '{"queued":true}';end if;
 if op='retention' then select coalesce(jsonb_agg(to_jsonb(v)),'[]') into result from(select id from private.work_jobs where organization_id=j.organization_id and kind='backup' and status in ('succeeded','blocked','failed') and created_at<clock_timestamp()-make_interval(days=>(select retention_days from private.app_settings where organization_id=j.organization_id)) and id not in(select id from private.work_jobs where organization_id=j.organization_id and kind='backup' and status='succeeded' order by created_at desc limit 2))v;return result;end if;
 if op='retire' then
 if not exists(select 1 from private.work_jobs x where x.id=(input->>'backup_id')::uuid and x.organization_id=j.organization_id and x.kind='backup' and x.status in ('succeeded','blocked','failed') and x.created_at<clock_timestamp()-make_interval(days=>(select retention_days from private.app_settings where organization_id=j.organization_id))) then raise exception 'Backup belum layak retensi';end if;
 update private.work_jobs set status='blocked',error='Artefak dihapus oleh retensi; riwayat dipertahankan',result_path=null where id=(input->>'backup_id')::uuid;delete from private.backup_rows where job_id=(input->>'backup_id')::uuid;return '{"saved":true}';end if;
 if op in ('complete','fail') then
 if op='complete' and j.kind='backup' and (input->>'path' not like j.organization_id::text||'/'||j.id::text||'/manifest.json' or input->>'sha256' !~ '^[0-9a-f]{64}$') then raise exception 'Manifest tidak valid';end if;
 update private.work_jobs set status=case when op='complete' then 'succeeded' when input->>'uncertain'='true' then 'uncertain' when input->>'blocked'='true' then 'blocked' else 'failed' end,progress=case when op='complete' then 100 else progress end,result_path=case when op='complete' then input->>'path' else result_path end,result_checksum=case when op='complete' then input->>'sha256' else result_checksum end,payload=case when op='complete' then payload||jsonb_build_object('outcome',coalesce(input->>'outcome','completed')) else payload end,error=case when op='complete' then null else left(input->>'message',500) end,next_attempt=clock_timestamp()+make_interval(mins=>power(2,least(5,attempts))::int),updated_at=clock_timestamp() where id=target;
 update public.job_runs set status=case when op='complete' then 'completed' else 'failed' end where organization_id=j.organization_id and kind=j.kind and idempotency_key=j.dedupe;
 if op='complete' and j.kind='backup' then delete from private.backup_rows where job_id=target;end if;
 insert into private.job_events(job_id,event,detail) values(target,op,case when op='complete' then null else left(input->>'message',500) end);
 insert into public.audit_logs(organization_id,actor_id,action,target_type,target_id) values(j.organization_id,j.requested_by,'JOB_'||j.kind||'_'||op,'work_jobs',target::text);return '{"saved":true}';end if;
 raise exception 'Aksi worker tidak dikenal';end$$;
create function public.worker_command(input jsonb) returns jsonb language sql security invoker set search_path='' as $$select private.worker_command(input)$$;
revoke all on function private.backup_data(uuid),private.backup_access(uuid),private.worker_command(jsonb),public.worker_command(jsonb) from public,anon,authenticated;
grant execute on function private.backup_access(uuid) to authenticated;
grant execute on function private.worker_command(jsonb),public.worker_command(jsonb) to service_role;
-- Preserve source bytes until an in-flight backup has copied them.
create function private.backup_holds_source(path text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from private.backup_rows b join private.work_jobs j on j.id=b.job_id where j.kind='backup' and j.status in ('queued','running','failed') and b.table_name='public.media_assets' and b.payload->>'object_path'=path)$$;
create or replace function private.source_delete_allowed(path text) returns boolean language sql stable security definer set search_path='' as $$select private.is_grader() and not private.attempt_media_frozen(path) and not private.backup_holds_source(path) and ((storage.foldername(path))[1]=auth.uid()::text or (private.is_admin() and (exists(select 1 from public.media_assets m where m.object_path=path and m.organization_id=private.actor_org()) or exists(select 1 from private.media_cleanup c where c.path=path and c.organization_id=private.actor_org()))))$$;
revoke all on function private.backup_holds_source(text) from public,anon,authenticated;
-- Include public branding references in existing source-media protection.
create or replace function private.media_referenced(mid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.question_versions v where v.payload->'attachments' ? mid::text) or exists(select 1 from private.attempt_questions q where q.student_payload->'attachments' ? mid::text) or exists(select 1 from private.report_settings s where s.logo_media_id=mid) or exists(select 1 from private.export_jobs j where j.settings_snapshot->>'logo_media_id'=mid::text) or exists(select 1 from private.card_jobs c where c.snapshot->'settings'->>'logo_media_id'=mid::text) or exists(select 1 from private.app_settings s where s.login_logo_id=mid or s.login_background_id=mid)$$;
create function private.semester_due(at_time timestamptz,zone text) returns text language sql stable set search_path='' as $$select case when to_char(at_time at time zone zone,'MM-DD') in ('06-30','12-31') and (at_time at time zone zone)::time>='23:30'::time then to_char(at_time at time zone zone,'YYYY')||case when extract(month from at_time at time zone zone)=6 then '-H1' else '-H2' end end$$;
create function private.scheduler_tick(at_time timestamptz default clock_timestamp()) returns jsonb language plpgsql security definer set search_path='' as $$declare org record;s private.app_settings;p public.authoring_periods;t record;a record;target uuid;semester text;progress jsonb;deficit int;dedupe text;begin
 if not pg_try_advisory_xact_lock(hashtext('edutara-scheduler')) then return '{"busy":true}';end if;
 for org in select * from public.organizations loop
 select * into s from private.app_settings where organization_id=org.id;if not found or not s.automation_enabled then continue;end if;
 -- One scheduler owns activation and timeout. Manual closures keep the existing engine semantics.
 update public.exams set status=case when at_time>=ends_at then 'closed' else 'active' end where organization_id=org.id and status in ('scheduled','active') and at_time>=starts_at and status is distinct from case when at_time>=ends_at then 'closed' else 'active' end;
 update public.exam_attempts ea set deadline_at=greatest(ea.started_at,least(ea.deadline_at,at_time)) where ea.organization_id=org.id and ea.finalized_at is null and exists(select 1 from public.exams e where e.id=ea.exam_id and e.status in ('closed','archived'));
 for a in select id from public.exam_attempts where organization_id=org.id and finalized_at is null and status in ('in_progress','disqualified') and deadline_at<=at_time order by id for update skip locked loop perform private.attempt_finalize(a.id,'timeout');end loop;
 semester:=private.semester_due(at_time,org.timezone);if semester is not null then perform private.enqueue_work(org.id,'backup','semester:'||semester,'{}',null);end if;
 if (select full_worker_approved from private.worker_transport) then perform private.enqueue_work(org.id,'retention','daily:'||to_char(at_time at time zone org.timezone,'YYYY-MM-DD'),'{}',null);end if;
 select * into p from public.authoring_periods where organization_id=org.id;
 if (select full_worker_approved from private.worker_transport) and s.reminders_enabled and p.enabled and p.ends_at>at_time and p.ends_at<=at_time+interval '24 hours' and extract(hour from at_time at time zone org.timezone) in (11,13,15,17,19,21,23) then
 for t in select pr.id,pr.full_name,u.email from public.profiles pr join auth.users u on u.id=pr.id where pr.organization_id=org.id and pr.role='teacher' and pr.active and u.email_confirmed_at is not null and u.email ~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' loop
 select coalesce(jsonb_agg(jsonb_build_object('exam',x.title,'exam_id',x.exam_id,'type',x.type,'missing',x.missing)),'[]'),coalesce(sum(x.missing),0) into progress,deficit from(select e.id exam_id,e.title,c.type,greatest(0,c.max_questions-(select count(*) from public.questions q where q.exam_id=e.id and q.type=c.type and q.archived_at is null)) missing from public.exams e join public.exam_type_configs c on c.exam_id=e.id and c.enabled and c.max_questions>0 where e.organization_id=org.id and e.status in ('draft','scheduled') and e.starts_at>at_time and exists(select 1 from public.exam_classes ec where ec.exam_id=e.id) and not exists(select 1 from public.exam_classes ec where ec.exam_id=e.id and not exists(select 1 from public.teacher_assignments ta where ta.teacher_id=t.id and ta.class_id=ec.class_id and ta.subject_id=e.subject_id and ta.active)))x where x.missing>0;
 if deficit>0 then dedupe:=p.starts_at::text||':'||p.ends_at::text||':'||t.id::text||':'||to_char(at_time at time zone org.timezone,'YYYY-MM-DD-HH24')||':'||encode(extensions.digest(s.reminder_template,'sha256'),'hex');perform private.enqueue_work(org.id,'reminder',dedupe,jsonb_build_object('teacher_id',t.id,'name',t.full_name,'email',lower(t.email),'period_end',p.ends_at,'deficit',progress,'template',s.reminder_template),null);end if;
 end loop;end if;
 end loop;
 update private.work_jobs set status=case when kind='reminder' and payload->>'delivery_started'='true' then 'uncertain' else 'failed' end,error='Worker lease berakhir; pengiriman yang tidak pasti memerlukan rekonsiliasi',next_attempt=at_time where status='running' and lease_until<at_time and attempts<5;
 for a in select id from private.work_jobs where status in ('queued','failed') and attempts<5 and next_attempt<=at_time order by created_at limit 20 for update skip locked loop perform private.dispatch_work(a.id);end loop;
 return jsonb_build_object('ticked_at',at_time);
end$$;
revoke all on function private.semester_due(timestamptz,text),private.scheduler_tick(timestamptz) from public,anon,authenticated;
grant execute on function private.scheduler_tick(timestamptz) to service_role;
-- Exactly one scheduler; repeated migration setup replaces the named job rather than duplicating it.
select cron.schedule('edutara-operations','* * * * *','select private.scheduler_tick();');
create function private.system_attempt_policy() returns trigger language plpgsql security definer set search_path='' as $$declare s private.app_settings;begin select * into s from private.app_settings where organization_id=new.organization_id;if found then new.policy_snapshot:=new.policy_snapshot||jsonb_build_object('canvas_enabled',s.canvas_enabled,'violation_limit',s.violation_limit);end if;return new;end$$;
revoke all on function private.system_attempt_policy() from public,anon,authenticated;
create trigger system_attempt_policy before insert on public.exam_attempts for each row execute function private.system_attempt_policy();
create function private.results_allowed(org uuid) returns boolean language sql stable security definer set search_path='' as $$select coalesce((select results_enabled from private.app_settings where organization_id=org),true)$$;
revoke all on function private.results_allowed(uuid) from public,anon,authenticated;
do $$declare body text;begin
 body:=pg_get_functiondef('private.attempt_dto(uuid)'::regprocedure);
 body:=replace(body,'e.show_exam_result and','private.results_allowed(a.organization_id) and e.show_exam_result and');
 body:=replace(body,'''payload'',q.student_payload','''payload'',case when coalesce((a.policy_snapshot->>''canvas_enabled'')::boolean,true) then q.student_payload else jsonb_set(q.student_payload,''{canvas,enabled}'',''false'') end');
 execute body;
 body:=pg_get_functiondef('private.attempt_command(jsonb)'::regprocedure);
 body:=replace(body,'if op=''canvas'' then','if op=''canvas'' then if not coalesce((a.policy_snapshot->>''canvas_enabled'')::boolean,true) then raise exception ''Canvas dinonaktifkan pada kebijakan attempt'';end if;');execute body;
 body:=pg_get_functiondef('private.can_upload_attempt_canvas(text)'::regprocedure);
 body:=replace(body,'a.status=''in_progress''','coalesce((a.policy_snapshot->>''canvas_enabled'')::boolean,true) and a.status=''in_progress''');execute body;
end$$;
create function private.session_audit(event_name text) returns void language plpgsql security definer set search_path='' as $$begin
 if private.actor_org() is null or event_name not in ('LOGOUT_REQUEST','LOGOUT_FAILED','PASSWORD_CHANGED') then raise exception 'AUTH: Event sesi tidak valid';end if;
 if not public.consume_login_budget('audit-session:'||auth.uid()::text||':'||event_name) then return;end if;
 insert into public.audit_logs(organization_id,actor_id,action,target_type,target_id) values(private.actor_org(),auth.uid(),event_name,'session',auth.jwt()->>'session_id');end$$;
create function public.session_audit(event_name text) returns void language sql security invoker set search_path='' as $$select private.session_audit(event_name)$$;
revoke all on function private.session_audit(text),public.session_audit(text) from public,anon;grant execute on function private.session_audit(text),public.session_audit(text) to authenticated;
